type Filters = { month:string; industry:string; discovery:string; sales:string; entity:string; usage:string; service:string; query:string; receipt:string; spend:string; sort:string; page:string };
const defaults: Filters = { month:'2026-09',industry:'ALL',discovery:'ALL',sales:'ALL',entity:'ALL',usage:'ALL',service:'ALL',query:'',receipt:'ALL',spend:'ALL',sort:'RECEIPTS_DESC',page:'1' };
function restoreFilters(value?:Partial<Filters>):Filters { const next={...defaults,...value};if(next.usage==='AWAITING_SERVICE')next.usage='NOT_STARTED';else if(!['ALL',...groups].includes(next.usage))next.usage='ALL';if(next.service==='รอเปิดบริการ')next.service='ALL';if(!['ALL','EVER','NEVER','UNKNOWN'].includes(next.receipt))next.receipt='ALL';if(!Object.hasOwn(spendLabels,next.spend))next.spend='ALL';if(!Object.hasOwn(sortLabels,next.sort))next.sort='RECEIPTS_DESC';if(!/^[1-9]\d*$/.test(next.page))next.page='1';return next; }
