type View={usage:string;revenue:string;customers:string;grouping:string;salesMode:string;compareBy:string;compareA:string;compareB:string};
const viewDefaults:View={usage:'adoption',revenue:'cash',customers:'industry',grouping:'industry',salesMode:'referrer',compareBy:'industry',compareA:'ร้านอาหาร',compareB:'ค้าปลีก'};
function restoreView(value?:Partial<View>,legacy?:any):View {
  const v={...viewDefaults,...value};
  for(const [key,allowed] of Object.entries({usage:['adoption','ranking'],revenue:['cash','pareto'],customers:['industry','source','sales'],grouping:['industry','entity'],salesMode:['referrer','credit'],compareBy:['industry','discovery','sales','company','period']}))if(!allowed.includes(v[key as keyof View]))v[key as keyof View]=viewDefaults[key as keyof View];
  if(legacy?.route==='analysis'&&legacy.filters?.spend&&legacy.filters.spend!=='ALL'&&!value)v.revenue='pareto';
  if(typeof v.compareA!=='string')v.compareA=viewDefaults.compareA;if(typeof v.compareB!=='string')v.compareB=viewDefaults.compareB;
  return v;
}
