    if(route==='usage'&&view.usage==='ranking'){visual.adoption=null;visual.bars=sorted.slice(0,10).filter(x=>usageValue(x,effectiveSort)!==null).map(x=>[x.name,usageValue(x,effectiveSort)!]);visual.barTitle=sortLabels[effectiveSort];visual.unit=effectiveSort==='ACTIVE_DAYS_DESC'?'วัน':effectiveSort==='AI_DESC'?'ครั้ง':'ใบ';}
