    setExportDraft({title,scope,count:new Set(population.map(x=>x.id)).size,fileName:`mangmee-executive-${route}-${filters.month}-demo.xlsx`,sheets,detail:companySheet,warning,visual});setExportSheet('0');setExportState('idle');
